"""Escaped payment acknowledgements from immutable invoice and payment snapshots."""
from quote_print import h,money,lines_text,details
from invoice_print import STYLE as INVOICE_STYLE
STYLE=INVOICE_STYLE+' .totals{width:410px;max-width:100%}.totals>div{gap:16px}.totals strong{white-space:nowrap;flex-shrink:0}.totals>div:last-child{font-size:18px}'
from invoice_rules import validate_invoice_document
from payment_rules import payment_record,METHODS,timestamp
from datetime import timezone

def render_receipt(inv,p):
    validate_invoice_document(inv);payment_record(p,inv)
    q=inv['quote_snapshot'];seller=q['seller_snapshot'];buyer={**q['customer_snapshot'],'address':inv['details']['billing_address']};d=p['details']
    test=p['is_test'];reversed=p['status']=='reversed'
    banner=('TEST — NO MONEY RECEIVED · PRACTICE ONLY' if test else '')+(' · ' if test and reversed else '')+('REVERSED — NOT VALID AS PROOF OF PAYMENT' if reversed else '')
    sums=''.join('<div><span>'+name+'</span><strong>'+money(v)+'</strong></div>' for name,v in [('Original invoice total',q['data']['total_cents']),('This payment'+(' (test)' if test else ''),d['amount_cents'])])
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+h(p['number'])+'</title><style>'+STYLE+'</style></head><body><p class="print-help">Use your browser’s Print command to print or save as PDF. <a href="/payments?invoice='+h(inv['id'])+'">Back to payments</a></p><div class="page-stamp">'+h(p['number'])+(' · '+h(banner) if banner else '')+'</div><main class="sheet">'+('<p class="draft">'+h(banner)+'</p>' if banner else '')+'<div class="heading"><div><h1>'+h(seller['name'])+'</h1><p>'+details(seller,['address','email','phone','website'])+'</p></div><div class="right"><h2>PAYMENT RECEIPT</h2><h2>'+h(p['number'])+'</h2><p>Payment date: '+h(d['payment_date'])+'<br>Invoice: '+h(inv['number'])+'<br>Currency: BSD</p></div></div><div class="parties"><div><div class="label">'+('Practice customer' if test else 'Received from')+'</div><strong>'+h(buyer['name'])+'</strong><p>'+details(buyer,['address','email','phone'])+'</p></div><div><div class="label">Payment details</div><p>Method: '+h(METHODS[d['method']])+'<br>Reference: '+h(d['reference'] or 'Not supplied')+'</p></div></div><h2>'+h(q['data']['title'])+'</h2><section class="totals">'+sums+'</section>'+('<section class="terms"><div class="label">Reversal</div><p>Reversed on '+h(timestamp(p['reversed_at']).astimezone(timezone.utc).strftime('%Y-%m-%d %H:%M UTC'))+'. Reason: '+lines_text(p['reversal_reason'])+'</p><p>This correction removes the recorded payment. It does not issue a refund.</p></section>' if reversed else '')+('<section class="terms"><div class="label">Payment note</div><p>'+lines_text(d['note'])+'</p></section>' if d['note'] else '')+'<p class="footer">'+('Test record only. This does not acknowledge an actual payment.' if test else 'Acknowledgement of the payment recorded against the invoice shown above. This is not a replacement VAT invoice.')+' View Payments or Credits &amp; refunds for the current balance including all payments, credits, refunds and corrections.</p></main></body></html>'
